from taf.gnb.oam.ne3s.ws.components.connection.messages import (
    NotificationMsg, NotificationGroup, AttachmentType, NotificationType)


class ATLNotification(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(ATLNotification, self).__init__(*args, **kwargs)

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(attachment, AttachmentType.Oats)
                and attachment.content is not None)


class ATLEmptyReportOperationalStatus(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(ATLEmptyReportOperationalStatus, self).__init__(*args, **kwargs)

    @staticmethod
    def matches(soap, attachment):
        is_attachment_none = (attachment is None
                              or (isinstance(attachment, AttachmentType.Oats)
                                  and attachment.content is None))
        return isinstance(soap, NotificationType.ReportOperationStatus) and is_attachment_none


class ATLNotificationGroup(NotificationGroup):
    QUEUE_IDS = ("atl_queue", )
    NOTIFICATIONS = (ATLNotification, ATLEmptyReportOperationalStatus)
